    let release;
    const blocked = new Promise((r) => (release = r));
    s.context.secrets.store = async (k, v) => {
      entered();
      await blocked;
      s.secrets.set(k, v);
    };
    const login = s.connection.login();
    await started;
    const logout = s.connection.disconnect();
    release();
    await Promise.all([login, logout]);
