  return model.dedicatedInfo.supportedNodes.flatMap((support) => {
    const node = hardware.get(support.nodeTypeName);
    if (
      !support.allowed ||
      support.maxContextSize <= 0 ||
      !node ||
      node.region !== 'fr-par' ||
      node.disabled ||
      (node.stockStatus !== 'available' && node.stockStatus !== 'low_stock')
