        quantization: { bits: body.quantization.bits },
        endpoints: [{ publicNetwork: {}, disableAuth: false }],
        tags: [],
        acceptEula: body.accept_eula,
      },
      { signal },
    );
  } catch {
    if (transportError) throw transportError;
    if (!captured)
      throw new ReadError(
        attempted ? 'creation_outcome_unknown' : 'invalid_request',
