    let done = false;
    let bytes = 0;
    const chunks: Buffer[] = [];
    let req: ReturnType<typeof https.request> | undefined;
    let timer: ReturnType<typeof setTimeout> | undefined;
    const end = (error?: ReadError, raw?: unknown) => {
      if (done) return;
      done = true;
      clearTimeout(timer);
      signal.removeEventListener('abort', cancel);
      req?.destroy();
      if (error) reject(error);
      else resolve(raw);
    };
    const unknown = () => end(new ReadError('creation_outcome_unknown'));
    const cancel = unknown;
    timer = setTimeout(unknown, 10000);
    signal.addEventListener('abort', cancel, { once: true });
    try {
      req = https.request(
        {
          hostname: 'api.scaleway.com',
          path,
          method: 'POST',
          agent: false,
          headers: {
            Accept: 'application/json',
            'Content-Type': 'application/json',
            'X-Auth-Token': secret,
          },
        },
        (res) => {
          const status = res.statusCode ?? 0;
          if (status < 200 || status >= 300) {
            res.destroy();
            return end(
              new ReadError(
                status === 401 || status === 403
                  ? 'access_denied'
                  : status === 400 || status === 422
                    ? 'creation_rejected'
                    : status === 429
                      ? 'rate_limited'
                      : 'creation_outcome_unknown',
