            bytes += chunk.length;
            if (bytes > 2 * 1024 * 1024) {
              res.destroy();
              unknown();
            } else chunks.push(chunk);
          });
          res.on('error', unknown);
          res.on('aborted', unknown);
          res.on('close', () => {
            if (!done) unknown();
          });
          res.on('end', () => {
            try {
              end(
                undefined,
                JSON.parse(
                  new TextDecoder('utf-8', { fatal: true }).decode(
                    Buffer.concat(chunks),
                  ),
                ),
              );
            } catch {
              unknown();
            }
          });
        },
      );
      req.on('error', unknown);
      if (signal.aborted) return cancel();
      req.end(body);
    } catch {
      unknown();
    }
  });
